head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS30201.xml';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.STD_CD = arrPar[0].STD_CD;
        scwin.objParam.ISU_NM = arrPar[0].BND_ISU_NM;
    }
};



/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 신용평가 수신정보 내역을 조회 한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_CLS_CREDIT_LIST';
    var qryId = 'lds.stf.bnscls.select.listCreditValuRcv';
    var param = '&{P}V_RCV_DD=' + $c.stf.getObjectValue(edt_StartDd);
    param += '&{P}V_RCV_DD_END=' + $c.stf.getObjectValue(edt_EndDd);
    param += '&{P}V_CREDIT_VALU_INST_NM=' + ''; //신용평가수신 및 처리 수신내역 목록 조회용도
    param += '&{P}V_SAME_GRD_YN=' + ''; //신용평가수신 및 처리 수신내역 목록 조회용도
    param += '&{P}V_STD_CD=' + scwin.objParam.STD_CD;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};

/********************************************** 
 * 함수명  	 : fn_delete
 * 설명       : 중복수신된 수신정보 내역을 삭제 한다.
 ***********************************************/
scwin.fn_delete = function() {
    // 등급기준이 선택된 값이 있는지 확인한다.
    var total = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "CHK") == "T") {
            total++;
        }
    }
    if (total == 0) {
        $c.win.alert("선택된 항목이 없습니다.");
        return;
    }
    if (!confirm("신용등급 데이터를 삭제하시겠습니까?")) return false;
    var V_RCV_DD;
    var V_CREDIT_VALU_INST_CD;
    var V_STD_CD;
    var V_RCV_ISU_NO;

    //선택된값 1개만 전송
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "CHK") == "T") {
            V_RCV_DD = dts_List.getCellData(i, "RCV_DD");
            V_CREDIT_VALU_INST_CD = dts_List.getCellData(i, "CREDIT_VALU_INST_CD");
            V_STD_CD = dts_List.getCellData(i, "STD_CD");
            V_RCV_ISU_NO = dts_List.getCellData(i, "RCV_ISU_NO");
        }
    }

    //삭제대상의 수신일체크 (당일 수신된 데이터만 삭제가능)
    //alert(vCurDate +'::'+ V_RCV_DD);
    if (scwin.vCurDate != V_RCV_DD) {
        $c.win.alert("당일 수신된 데이터만 삭제 할 수 있습니다.");
        return;
    }
    var url = "/bns/CreditValu.do?method=processCreditValuRcvDelete";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&RCV_DD=" + V_RCV_DD;
    url += "&CREDIT_VALU_INST_CD=" + V_CREDIT_VALU_INST_CD;
    url += "&STD_CD=" + V_STD_CD;
    url += "&RCV_ISU_NO=" + V_RCV_ISU_NO;
    //alert(url);

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};



/**
 * 마지막 선택 row만 체크박스 선택
 */
scwin.fn_Check = function(nRow, colid) {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        dts_List.setCellData(i, "CHK", "F");
    }
    dts_List.setCellData(nRow, "CHK", "T");
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Srch);

    //호출파라미터설정
    scwin.fn_SetParam();

    //종목정보 설정
    var vIsuNm = '[' + scwin.objParam.STD_CD + ']' + '  ' + '[' + scwin.objParam.ISU_NM + ']';
    $c.stf.setObjectValue(txb_StdCd, vIsuNm);

    //수신일 시작일 현재일자 -10일로 설정, 수신일 종료일 현재일자로 설정 
    $c.stf.setObjectValue(edt_StartDd, $c.ut.cGetMinusDate2(scwin.vCurDate, 10));
    $c.stf.setObjectValue(edt_EndDd, scwin.vCurDate);

    //신용평가 수신정보 내역 조회
    scwin.fn_list_sync();
};
scwin.img_StartDd_onclick = function() {
    popUpCalendar2(edt_StartDd);
};
scwin.img_EndDd_onclick = function() {
    popUpCalendar2(edt_EndDd);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Srch_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Delete_onclick = function() {
    if (dts_List.getTotalRow() == 0) return;
    processGp = 5;
    scwin.fn_delete();
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_Check(row, colid);
};
scwin.trs_Save_OnSuccess = function() {
    if (processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    }
    if (processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    }
    dts_List.Reset();
};
scwin.trs_Save_OnFail = function() {
    if (processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
    if (processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
